# targetgen DSpark drafter for Dr. Doom on a 210k-row SUBSET of the Datakit rows already regenerated by ../dspark_grug-67b-a2b-datakit-sft-dr-doom_datakit-sft-mix_targetgen (400k rows, 17.2 h of regeneration + 5.7 h of training = 22.8 h).
# 210k rows cost 0.525 of that: about 9.0 h of regeneration (not rerun: the replies are reused) + about 3.0 h of training = about 12 h in total. Nothing is regenerated here: the train stage merges the selected parts, then trains one epoch.
# Sourced after env.sh (needs PROJECT_ROOT and EXP_DIR). It starts from the parent's settings and assigns, OUTRIGHT, every path that must be fresh.
PARENT_EXP="$(cd "$EXP_DIR/../dspark_grug-67b-a2b-datakit-sft-dr-doom_datakit-sft-mix_targetgen" && pwd)"
source "$PARENT_EXP/settings.sh"

WORK_DIR="$PROJECT_ROOT/runs/grug_dspark_drdoom_targetgen_210k"          # fresh, assigned outright
case "$(basename "$WORK_DIR")" in
    grug_dspark_full|grug_dspark_onpolicy|grug_dspark_itw_drdoom|grug_dspark_drdoom_targetgen|grug_dspark_drdoom_targetgen_warm80k|grug_dspark_itw_rlsimilar|grug_dspark_itw_ffn3x|grug_dspark_itw_drdoom_perfectblend|grug_dspark_itw_drdoom_big_pool|grug_dspark_drdoom_big_pool_targetgen) echo "settings.sh: WORK_DIR $WORK_DIR is an old run's directory" >&2; return 1 2>/dev/null || exit 1 ;;
esac
PARTS_DIR="$WORK_DIR/regen_parts"                 # the selected parts, copied by data/select_parts.py from the parent's run (runs/grug_dspark_drdoom_targetgen/regen_parts, READ ONLY)
DATA_DIR="$WORK_DIR/data"
CKPT_DIR="$WORK_DIR/checkpoints"
LOG_DIR="$WORK_DIR/logs"
REGEN_PARTS_SRC=""                                # parts are placed in PARTS_DIR by select_parts.py; no import (the import would copy ALL 800 parts)
REGEN_ROWS=210000                                 # documentation only: the regen stage is not run
LOGGER_ARGS=()
if [[ -n "$LOGGER" ]]; then LOGGER_ARGS=(--logger "$LOGGER" --run-name "$RUN_NAME" --log-dir "$LOG_DIR/tracker"); fi
HF_DESCRIPTION="DSpark drafter (3 layers, FFN 3840) for open-athena/Grug-67B-A2B-Datakit-SFT-262K-2026.09.21-dr-doom, trained from random initialisation on Dr. Doom's own replies to 210k Datakit SFT conversations (targetgen only; a random half of the 400k-row run's replies)."
_BASE_PATH="$PATH"
use_env() {
    unset CUDA_HOME _VLLM_OLD_PATH                      # what `conda deactivate` of the other env would undo
    export CONDA_PREFIX="$PROJECT_ROOT/envs/$1" PATH="$PROJECT_ROOT/envs/$1/bin:$_BASE_PATH"
    set +u; for _f in "$CONDA_PREFIX"/etc/conda/activate.d/*.sh; do [[ -f "$_f" ]] && source "$_f"; done; set -u
}
